"""Deterministic structural check for the CVE-2017-17712 backport.

Run from a checkout root; inspects net/ipv4/raw.c and asserts the
single-snapshot invariant inside raw_sendmsg().
"""
import re
import sys

PATH = "net/ipv4/raw.c"


def main() -> int:
    src = open(PATH, encoding="utf-8").read()
    try:
        start = src.index("static int raw_sendmsg(")
        end = src.index("\nstatic int raw_recvmsg(", start)
    except ValueError as exc:
        print("FAIL: cannot delimit raw_sendmsg: %s" % exc)
        return 1
    body = src[start:end]
    errors = []

    if "int hdrincl;" not in body:
        errors.append("local `int hdrincl;` declaration missing")
    if "inet->hdrincl" in body:
        errors.append("raw_sendmsg still reads inet->hdrincl directly")

    snap = re.search(r"\bhdrincl\s*=\s*inet->hdrincl\s*;", body)
    if not snap:
        errors.append("snapshot assignment `hdrincl = inet->hdrincl;` missing")

    decisions = {
        "if (hdrincl)": 2,
        "if (!hdrincl)": 1,
        "hdrincl ? IPPROTO_RAW": 1,
        "hdrincl ? FLOWI_FLAG_KNOWN_NH": 1,
    }
    for token, expected in decisions.items():
        found = body.count(token)
        if found != expected:
            errors.append("expected %d occurrence(s) of %r, found %d" % (expected, token, found))

    if snap:
        positions = [body.find(tok) for tok in decisions]
        positions = [p for p in positions if p >= 0]
        if positions and snap.start() > min(positions):
            errors.append("snapshot assignment occurs after a hdrincl decision point")

    whole_file_reads = src.count("inet->hdrincl")
    # one read remains in the ICMP error path (different function), plus the
    # snapshot assignment counts as the 2nd textual occurrence.
    if whole_file_reads != 2:
        errors.append(
            "expected exactly 2 textual `inet->hdrincl` occurrences "
            "(ICMP path + snapshot), found %d" % whole_file_reads
        )

    if errors:
        for err in errors:
            print("FAIL: " + err)
        return 1
    print("OK: raw_sendmsg reads inet->hdrincl exactly once into local `hdrincl`; "
          "all four hdrincl decision sites use the snapshot")
    return 0


if __name__ == "__main__":
    sys.exit(main())

